#nullable enable // autogenerated

using PVZEngine.Tools.Unity;
using MVZ2Logic.UI;
using UnityEngine;
using UnityEngine.UI;

namespace MVZ2.UI.Archive
{
    public class SimulationArchivePage : ArchivePage
    {
        public void SetShake(Vector3 shake)
        {
            if (shakeRoot.Exists())
            {
                shakeRoot.localPosition = shake;
            }
        }
        public void SetBackground(Sprite? background)
        {
            backgroundImage.SetSprite(background);
            if (background.Exists())
            {
                backgroundRatioFitter.aspectRatio = background.rect.width / background.rect.height;
            }
        }
        [SerializeField]
        private RectTransform shakeRoot = null!;
        [SerializeField]
        private ImageResolver backgroundImage = null!;
        [SerializeField]
        private AspectRatioFitter backgroundRatioFitter = null!;
    }
}
